import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1.2e-5"));
        assertTrue(NumberUtils.isNumber("1.2E+5"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("1e"));
        assertFalse(NumberUtils.isNumber("1e1.2")); // Dec in exponent not allowed by code logic
        assertFalse(NumberUtils.isNumber("1e1e1"));
        assertFalse(NumberUtils.isNumber("1e+"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123g"));
        // l/L not allowed with exponent per code: return foundDigit && !hasExp;
        assertFalse(NumberUtils.isNumber("1e10l"));
        assertFalse(NumberUtils.isNumber("1e10L"));

        // Qualifiers with decimals
        assertTrue(NumberUtils.isNumber("123.45f"));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {













    @Test
    public void testIsNumber_EdgeCasesAndBranches() {
        // Single digit with sign
        assertTrue(NumberUtils.isNumber("-1"));

        // Test the "allowSigns" logic in the loop for the last char
        // Specifically: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This handles cases like "1E-" where it might try to validate the sign
        assertFalse(NumberUtils.isNumber("1E-"));
        assertFalse(NumberUtils.isNumber("1E+"));

        // Test the logic: if (chars[i] == '.') return foundDigit;
        assertTrue(NumberUtils.isNumber("1."));
        assertFalse(NumberUtils.isNumber("."));

        // Test decimal point and exponent combo
        assertFalse(NumberUtils.isNumber("1.2e1.2")); 

        // Test the sign logic after E
        assertTrue(NumberUtils.isNumber("1E2"));
        assertTrue(NumberUtils.isNumber("1E-2"));
        assertTrue(NumberUtils.isNumber("1E+2"));

        // Test character boundaries
        assertFalse(NumberUtils.isNumber(" "));
        assertFalse(NumberUtils.isNumber("12 3"));

        // Test the logic for '-' at the very start
        // start = (chars[0] == '-') ? 1 : 0;
        assertTrue(NumberUtils.isNumber("-0x123")); // Wait, looking at code:
        // if (sz > start + 1) { if (chars[start] == '0' && chars[start + 1] == 'x') ... }
        // If str is "-0x123", start is 1. chars[1] is '0', chars[2] is 'x'. This should return true.
        assertTrue(NumberUtils.isNumber("-0x123"));

        // Test invalid characters at end
        assertFalse(NumberUtils.isNumber("123?"));
    }
}
